<?php
declare(strict_types=1);
namespace SimpleMSPDoc\Modules\Records;
use SimpleMSPDoc\Core\{AccessPolicy,Context,HttpException,RecordRepository,RecordScope};
use SimpleMSPDoc\Modules\{Assets\TemplateService,Organizations\OrganizationService,Files\AttachmentService,Relationships\RelationshipService};
final class RecordController
{
 public function __construct(private Context $ctx){}
 private function record(int $id,bool $trash=false): array {return (new RecordRepository($this->ctx->db))->get($this->ctx->actor,$id,null,$trash);}
 private function writable(array $r): bool {return (new AccessPolicy($this->ctx->db))->can($this->ctx->actor,'write',new RecordScope((int)$r['organization_id'],$r['visibility']));}
 private function files(): AttachmentService {return new AttachmentService($this->ctx->db,$this->ctx->audit,$this->ctx->privateRoot.'/data/uploads',$this->ctx->config['upload_limit']??20971520);}
 private function links(): RelationshipService {return new RelationshipService($this->ctx->db,$this->ctx->audit);}
 public function index(array $params): void {$org=(new OrganizationService($this->ctx->db,$this->ctx->audit))->get($this->ctx->actor,(int)$params['org']);$type=$params['type'];$trash=!empty($_GET['trash']);$page=max(1,(int)($_GET['page']??1));$this->ctx->render('records/index',['title'=>['asset'=>'Configurations','article'=>'Documents','contact'=>'Contacts','location'=>'Locations'][$type],'organization'=>$org,'type'=>$type,'records'=>$this->ctx->records($type)->list($this->ctx->actor,(int)$org['id'],$trash,$page),'trash'=>$trash,'page'=>$page,'canWrite'=>(new AccessPolicy($this->ctx->db))->can($this->ctx->actor,'write',new RecordScope((int)$org['id']))]);}
 public function form(array $params): void {
  $r=isset($params['id'])?$this->record((int)$params['id']):null;$orgId=(int)($r['organization_id']??$params['org']);$type=$r['type']??$params['type'];(new AccessPolicy($this->ctx->db))->require($this->ctx->actor,'write',new RecordScope($orgId,$r['visibility']??'internal'));$org=(new OrganizationService($this->ctx->db,$this->ctx->audit))->get($this->ctx->actor,$orgId);$templates=[];$definition=null;$locations=[];$contacts=[];
  if($type==='asset'){$t=new TemplateService($this->ctx->db,$this->ctx->audit);$templates=$t->list();$templateId=(int)($r['payload']['template_id']??$_GET['template']??($templates[0]['id']??0));$definition=$t->get($templateId);$locations=$this->ctx->records('location')->list($this->ctx->actor,$orgId);$contacts=$this->ctx->records('contact')->list($this->ctx->actor,$orgId);}
  $this->ctx->render('records/form',['title'=>($r?'Edit ':'New ').['asset'=>'configuration','article'=>'document','contact'=>'contact','location'=>'location'][$type],'record'=>$r,'organization'=>$org,'type'=>$type,'templates'=>$templates,'definition'=>$definition,'locations'=>$locations,'contacts'=>$contacts]);
 }
 private function input(string $type): array {
  $input=['title'=>$_POST['title']??'','visibility'=>$_POST['visibility']??'internal','category'=>$_POST['category']??'','tags'=>$_POST['tags']??''];$input['payload']=match($type){'article'=>['html'=>$_POST['html']??''],'location'=>['address'=>$_POST['address']??'','phone'=>$_POST['phone']??'','notes'=>$_POST['notes']??''],'contact'=>['email'=>$_POST['email']??'','phone'=>$_POST['phone']??'','position'=>$_POST['position']??'','notes'=>$_POST['notes']??''],'asset'=>['template_id'=>(int)($_POST['template_id']??0),'values'=>$_POST['values']??[],'notes'=>$_POST['notes']??'','location_id'=>$_POST['location_id']??null,'contact_id'=>$_POST['contact_id']??null],default=>throw new HttpException(404,'Record type not found.')};return $input;
 }
 public function save(array $params): void {
  if(isset($params['id'])){$r=$this->record((int)$params['id']);$id=(int)$r['id'];$service=$this->ctx->records($r['type']);$input=$this->input($r['type']);if($r['type']==='article')$service->update($this->ctx->actor,$id,$input,isset($_POST['revision'])?(int)$_POST['revision']:null);else $service->update($this->ctx->actor,$id,$input);}
  else{$id=$this->ctx->records($params['type'])->create($this->ctx->actor,(int)$params['org'],$this->input($params['type']));}
  $this->ctx->flash('Documentation saved.');$this->ctx->redirect('/records/'.$id);
 }
 public function show(array $params): void {
  $r=$this->record((int)$params['id']);$w=$this->writable($r);$org=(new OrganizationService($this->ctx->db,$this->ctx->audit))->get($this->ctx->actor,(int)$r['organization_id']);$definition=null;$references=[];$history=[];$targets=[];
  if($r['type']==='asset'){$definition=(new TemplateService($this->ctx->db,$this->ctx->audit))->get((int)$r['payload']['template_id']);foreach(['location_id','contact_id'] as $key)if(!empty($r['payload'][$key])){try{$target=$this->record((int)$r['payload'][$key]);$references[]=[$key,$target];}catch(HttpException $e){if($e->status!==404)throw $e;}}}
  if($r['type']==='article'&&$this->ctx->actor->audience==='staff')$history=$this->ctx->records('article')->history($this->ctx->actor,(int)$r['id']);
  if($w)foreach(['asset','article','location','contact'] as $t)foreach($this->ctx->records($t)->list($this->ctx->actor,(int)$r['organization_id']) as $target)if($target['id']!==$r['id'])$targets[]=$target;
  $this->ctx->render('records/show',['title'=>$r['title'],'record'=>$r,'organization'=>$org,'canWrite'=>$w,'definition'=>$definition,'references'=>$references,'history'=>$history,'attachments'=>$this->files()->list($this->ctx->actor,(int)$r['id']),'relationships'=>$this->links()->listVisible($this->ctx->actor,$r['type'],(int)$r['id']),'targets'=>$targets,'linkedPasswords'=>$r['type']==='asset'?(new \SimpleMSPDoc\Modules\Passwords\PasswordService($this->ctx->db,$this->ctx->audit,$this->ctx->config['key']))->list($this->ctx->actor,(int)$r['organization_id'],(int)$r['id']):[]]);
 }
 public function archive(array $params): void {$r=$this->record((int)$params['id']);$this->ctx->records($r['type'])->archive($this->ctx->actor,(int)$r['id']);$this->ctx->flash('Record archived.');$this->ctx->redirect('/organizations/'.$r['organization_id'].'/'.$r['type']);}
 public function restore(array $params): void {$r=$this->record((int)$params['id'],true);$this->ctx->records($r['type'])->restore($this->ctx->actor,(int)$r['id']);$this->ctx->flash('Record restored.');$this->ctx->redirect('/records/'.$r['id']);}
 public function upload(array $params): void {$r=$this->record((int)$params['id']);$file=$_FILES['attachment']??[];if(!is_uploaded_file($file['tmp_name']??''))throw new HttpException(422,'Select an uploaded file.');$this->files()->upload($this->ctx->actor,$r['type'],(int)$r['id'],$file);$this->ctx->flash('Attachment uploaded.');$this->ctx->redirect('/records/'.$r['id']);}
 public function download(array $params): void {$a=$this->files()->download($this->ctx->actor,(int)$params['id']);header('Content-Type: '.$a['mime']);header('Content-Length: '.$a['bytes']);header('Content-Disposition: attachment; filename="download"; filename*=UTF-8\'\''.rawurlencode($a['name']));header("Content-Security-Policy: default-src 'none'; sandbox");$stream=\SimpleMSPDoc\Core\ProtectedFile::open($a['path']);try{fpassthru($stream);}finally{fclose($stream);}}
 public function deleteAttachment(array $params): void {$a=$this->files()->download($this->ctx->actor,(int)$params['id']);$this->files()->delete($this->ctx->actor,(int)$params['id']);$this->ctx->redirect('/records/'.$a['record_id']);}
 public function relate(array $params): void {$s=$this->record((int)$params['id']);$t=$this->record((int)($_POST['target_id']??0));$this->links()->link($this->ctx->actor,$s['type'],(int)$s['id'],$t['type'],(int)$t['id']);$this->ctx->redirect('/records/'.$s['id']);}
 public function unrelate(array $params): void {$this->links()->unlink($this->ctx->actor,(int)$params['id'],(int)$params['relationship']);$this->ctx->redirect('/records/'.$params['id']);}
 public function revision(array $params): void {if($this->ctx->actor->audience==='client')throw new HttpException(403,'Article history is available to staff only.');$r=$this->record((int)$params['id']);if($r['type']!=='article')throw new HttpException(404,'Article not found.');$rev=$this->ctx->records('article')->revision($this->ctx->actor,(int)$r['id'],(int)$params['revision']);$this->ctx->render('records/revision',['title'=>'Article revision','record'=>$r,'revision'=>$rev,'canWrite'=>$this->writable($r)]);}
 public function restoreRevision(array $params): void {$this->ctx->records('article')->restoreRevision($this->ctx->actor,(int)$params['id'],(int)$params['revision'],(int)($_POST['expected_revision']??0));$this->ctx->flash('Earlier content restored as a new revision.');$this->ctx->redirect('/records/'.$params['id']);}
}
